-- 2. Transform duplicate slots (46-65) into dedicated Topic Quiz questions
UPDATE questions SET question_type = 'QUIZ', question_text = 'What is the memory size and encoding format of a `char` primitive in Java?', option_a = '8 bits, ASCII encoding', option_b = '16 bits, Unicode (UTF-16) encoding', option_c = '32 bits, UTF-32 encoding', option_d = '64 bits, binary float', correct_option = 'B', explanation = 'In Java, a char is an unsigned 16-bit integer (0 to 65,535) capable of representing standard Unicode characters in UTF-16.', hint = NULL WHERE id = 46;
UPDATE questions SET question_type = 'QUIZ', question_text = 'What happens when an `int` variable holding `Integer.MAX_VALUE` has 1 added to it (`int x = Integer.MAX_VALUE + 1;`)?', option_a = 'Throws an ArithmeticException', option_b = 'It overflows and wraps around to `Integer.MIN_VALUE` (-2,147,483,648)', option_c = 'It clamps at Integer.MAX_VALUE', option_d = 'Automatically promotes to long', correct_option = 'B', explanation = 'Java integer arithmetic uses two''s complement without overflow exceptions; exceeding Integer.MAX_VALUE rolls over into negative values.', hint = NULL WHERE id = 47;
UPDATE questions SET question_type = 'QUIZ', question_text = 'Which of the following identifiers is ILLEGAL according to Java language syntax rules?', option_a = '_studentCount', option_b = '$totalAmount', option_c = '2ndAttempt', option_d = 'user_name_2026', correct_option = 'C', explanation = 'Java identifiers cannot begin with a decimal digit (0-9). They must start with a letter, currency character ($), or underscore (_).', hint = NULL WHERE id = 48;
UPDATE questions SET question_type = 'QUIZ', question_text = 'What occurs if a `break` statement is omitted from a matched `case` inside a traditional Java `switch` block?', option_a = 'Compile-time error', option_b = 'Fall-through execution occurs into subsequent cases regardless of their case values', option_c = 'The switch block terminates immediately', option_d = 'The program halts', correct_option = 'B', explanation = 'Without break, execution falls through into following case statements sequentially until a break or end of switch is reached.', hint = NULL WHERE id = 50;
UPDATE questions SET question_type = 'QUIZ', question_text = 'Can a standard Java `switch` statement evaluate a `String` expression?', option_a = 'No, switch only supports primitive integers', option_b = 'Yes, String support in switch statements was added in Java 7', option_c = 'Only if string length is under 5 characters', option_d = 'Only for char types', correct_option = 'B', explanation = 'Since Java 7, String expressions are fully supported in switch statements using String.equals() behind the scenes.', hint = NULL WHERE id = 51;
UPDATE questions SET question_type = 'QUIZ', question_text = 'What is printed by: `int a = 2; if (a++ > 2) System.out.print("X"); else System.out.print("Y"); System.out.print(a);`?', option_a = 'X2', option_b = 'Y3', option_c = 'X3', option_d = 'Y2', correct_option = 'B', explanation = 'Post-increment a++ evaluates using original value 2 (2 > 2 is false -> prints ''Y''), then increments a to 3 -> prints ''3'', yielding ''Y3''.', hint = NULL WHERE id = 52;
UPDATE questions SET question_type = 'QUIZ', question_text = 'Where are Java arrays allocated during runtime memory management?', option_a = 'Always in Stack memory', option_b = 'Always on the Heap, even when containing primitive values', option_c = 'In the CPU cache registers', option_d = 'In the Metaspace', correct_option = 'B', explanation = 'All arrays in Java are true objects and are allocated on the garbage-collected Heap. The variable name merely holds a stack reference address.', hint = NULL WHERE id = 54;
UPDATE questions SET question_type = 'QUIZ', question_text = 'Given `int[] a = {1, 2, 3}; int[] b = a; b[0] = 99;`, what does `System.out.println(a[0]);` print?', option_a = '1', option_b = '99', option_c = '0', option_d = 'NullPointerException', correct_option = 'B', explanation = 'Array assignment b = a copies the reference address, not the array elements. Both a and b reference the identical heap array.', hint = NULL WHERE id = 55;
UPDATE questions SET question_type = 'QUIZ', question_text = 'What method in `java.util.Arrays` copies an array into a new array of specified length?', option_a = 'Arrays.duplicate()', option_b = 'Arrays.copyOf()', option_c = 'Arrays.slice()', option_d = 'Arrays.cloneArray()', correct_option = 'B', explanation = 'Arrays.copyOf(original, newLength) allocates and returns a new array containing copies of the original elements.', hint = NULL WHERE id = 56;
UPDATE questions SET question_type = 'QUIZ', question_text = 'What is the primary architectural purpose of data encapsulation in OOP?', option_a = 'To make classes execute faster', option_b = 'To hide internal class state and protect invariants by controlling mutation through methods', option_c = 'To allow multiple inheritance', option_d = 'To prevent garbage collection', correct_option = 'B', explanation = 'Encapsulation bundles data and logic together while hiding internal implementation details, preventing external code from corrupting state.', hint = NULL WHERE id = 57;
UPDATE questions SET question_type = 'QUIZ', question_text = 'If a Java class contains no explicit constructor definitions, what does the Java compiler supply?', option_a = 'No constructor is created, preventing instantiation', option_b = 'A default no-argument constructor with the same access modifier as the class', option_c = 'A constructor taking null for all fields', option_d = 'A private constructor', correct_option = 'B', explanation = 'If no constructor is declared in source code, the compiler automatically generates a no-argument default constructor.', hint = NULL WHERE id = 58;
UPDATE questions SET question_type = 'QUIZ', question_text = 'Can a `static` method directly invoke a non-static instance method within the same class without an object reference?', option_a = 'Yes, at any time', option_b = 'No, because static methods execute without a `this` instance context', option_c = 'Only if the instance method is public', option_d = 'Only if declared synchronized', correct_option = 'B', explanation = 'Static methods belong to the class namespace and have no this context, so they cannot directly access instance fields or instance methods.', hint = NULL WHERE id = 59;
UPDATE questions SET question_type = 'QUIZ', question_text = 'What happens if a subclass constructor does NOT explicitly call `super(...)` or `this(...)` on its first line?', option_a = 'The program fails to compile', option_b = 'The compiler automatically inserts an implicit no-argument `super()` call', option_c = 'The parent constructor is never executed', option_d = 'Memory leak occurs', correct_option = 'B', explanation = 'If not specified, Java compiler automatically places super() as the first statement to ensure superclass state is properly initialized.', hint = NULL WHERE id = 60;
UPDATE questions SET question_type = 'QUIZ', question_text = 'What is dynamic method dispatch (runtime polymorphism) in Java?', option_a = 'Resolving method calls at compile-time', option_b = 'Resolving calls to overridden methods at runtime based on the actual object type', option_c = 'Calling private methods from other packages', option_d = 'Inlining bytecode during execution', correct_option = 'B', explanation = 'Dynamic method dispatch enables Java to determine at runtime which overridden method implementation to execute based on the target object.', hint = NULL WHERE id = 61;
UPDATE questions SET question_type = 'QUIZ', question_text = 'Can an interface in modern Java (Java 8+) declare a method with a concrete body?', option_a = 'No, interfaces can never contain concrete code', option_b = 'Yes, using the `default` or `static` method modifiers', option_c = 'Only if marked native', option_d = 'Only in package-private interfaces', correct_option = 'B', explanation = 'Java 8 introduced default and static methods in interfaces, allowing backwards-compatible default implementations.', hint = NULL WHERE id = 62;
UPDATE questions SET question_type = 'QUIZ', question_text = 'What is the common base class of all error and exception types in the Java language?', option_a = 'java.lang.Exception', option_b = 'java.lang.Error', option_c = 'java.lang.Throwable', option_d = 'java.lang.RuntimeException', correct_option = 'C', explanation = 'java.lang.Throwable is the superclass of all exceptions and errors in the Java programming language.', hint = NULL WHERE id = 63;
UPDATE questions SET question_type = 'QUIZ', question_text = 'What occurs if an exception is thrown in a `try` block and NO matching `catch` block exists?', option_a = 'The exception is ignored', option_b = 'The `finally` block (if present) executes, then the exception propagates up the call stack', option_c = 'The application instantly crashes without finally', option_d = 'It retries the try block', correct_option = 'B', explanation = 'The finally block executes before the unhandled exception propagates up the call stack to the calling method.', hint = NULL WHERE id = 64;
UPDATE questions SET question_type = 'QUIZ', question_text = 'What is the average time complexity of `get()` and `put()` operations in a well-distributed `HashMap`?', option_a = 'O(log N)', option_b = 'O(1) constant time', option_c = 'O(N) linear time', option_d = 'O(N log N)', correct_option = 'B', explanation = 'With a uniform hash distribution, HashMap provides O(1) average time complexity for key lookups and inserts.', hint = NULL WHERE id = 65;

-- 3. Insert additional Topic Quiz questions to ensure 5 questions per topic
INSERT INTO questions (topic_id, question_text, option_a, option_b, option_c, option_d, correct_option, question_type, explanation, hint) VALUES (3, 'What is the return value of `Arrays.binarySearch(sortedArray, key)` if the search key is NOT present in the sorted array?', '0', '-1', 'A negative integer representing `-(insertion point) - 1`', 'Throws NoSuchElementException', 'C', 'QUIZ', 'If key is absent, binarySearch returns -(insertion point) - 1, providing both absence notification and the index where it should be inserted.', NULL);
INSERT INTO questions (topic_id, question_text, option_a, option_b, option_c, option_d, correct_option, question_type, explanation, hint) VALUES (4, 'Which keyword applied to a class declaration prevents any other class from extending it?', 'abstract', 'static', 'final', 'sealed without permits', 'C', 'QUIZ', 'Declaring a class final prohibits inheritance. For example, java.lang.String is a final class.', NULL);
INSERT INTO questions (topic_id, question_text, option_a, option_b, option_c, option_d, correct_option, question_type, explanation, hint) VALUES (5, 'Can a subclass override a `private` method declared in its superclass?', 'Yes, by adding @Override', 'No, private methods are not visible to subclasses and therefore cannot be overridden', 'Only if both classes share the same package', 'Yes, if declared protected', 'B', 'QUIZ', 'Because private methods are completely invisible outside the declaring class, a subclass cannot override them.', NULL);
INSERT INTO questions (topic_id, question_text, option_a, option_b, option_c, option_d, correct_option, question_type, explanation, hint) VALUES (6, 'Which Collection interface preserves insertion order and allows duplicate elements?', 'Set', 'List', 'Map', 'Queue without priority', 'B', 'QUIZ', 'List is an ordered collection (sequence) that allows precise element placement and duplicate entries.', NULL);

-- 4. Insert 18 Distinct Final Course Assessment questions (3 per topic)
INSERT INTO questions (topic_id, question_text, option_a, option_b, option_c, option_d, correct_option, question_type, explanation, hint) VALUES (1, 'Given `byte a = 10; byte b = 20; byte c = (byte)(a + b);`, why is the explicit `(byte)` cast mandatory?', 'Java arithmetic operators automatically promote byte operands to 32-bit `int` before calculation', 'Because byte addition is not supported in Java', 'Because 10 + 20 exceeds byte capacity', 'To prevent memory leaks', 'A', 'FINAL_ASSESSMENT', 'Java evaluates binary arithmetic on byte and short values by automatically promoting operands to 32-bit int. Storing the result back into a byte requires an explicit narrowing cast.', NULL);
INSERT INTO questions (topic_id, question_text, option_a, option_b, option_c, option_d, correct_option, question_type, explanation, hint) VALUES (1, 'What does `double d = 0.1 + 0.2; System.out.println(d == 0.3);` output in Java, and why?', 'true, because math calculations are exact', 'false, due to IEEE 754 floating-point binary representation precision limits', 'Compilation error', 'NullPointerException', 'B', 'FINAL_ASSESSMENT', 'Binary floating-point types cannot represent fractional base-10 values like 0.1 exactly, resulting in ~0.30000000000000004, so equality returns false.', NULL);
INSERT INTO questions (topic_id, question_text, option_a, option_b, option_c, option_d, correct_option, question_type, explanation, hint) VALUES (1, 'When an object reference is passed as an argument to a Java method, what does Java pass?', 'A deep clone of the entire object', 'A copy of the reference address value (pass-by-value)', 'The actual pointer by reference (pass-by-reference)', 'The object''s byte code', 'B', 'FINAL_ASSESSMENT', 'Java is strictly pass-by-value. When passing an object, a copy of the reference address is passed into the parameter variable.', NULL);
INSERT INTO questions (topic_id, question_text, option_a, option_b, option_c, option_d, correct_option, question_type, explanation, hint) VALUES (2, 'How does a labeled `break` statement (`break searchLabel;`) behave inside nested loops?', 'It terminates all threads in the application', 'It breaks out of the specific outer loop identified by the label', 'It pauses execution for 500ms', 'It restarts the outer loop from index 0', 'B', 'FINAL_ASSESSMENT', 'Labeled break allows clean escape from deeply nested iteration loops directly to the statement immediately following the labeled block.', NULL);
INSERT INTO questions (topic_id, question_text, option_a, option_b, option_c, option_d, correct_option, question_type, explanation, hint) VALUES (2, 'What is printed by: `int c = 0; for(int i = 0; i < 3; i++) for(int j = 0; j < 2; j++) { if (i == j) continue; c++; } System.out.println(c);`?', '6', '4', '2', '0', 'B', 'FINAL_ASSESSMENT', 'Total loop cycles = 3 * 2 = 6. Matches i == j occur at (0,0) and (1,1) [2 times]. Skipping these leaves 6 - 2 = 4 increments.', NULL);
INSERT INTO questions (topic_id, question_text, option_a, option_b, option_c, option_d, correct_option, question_type, explanation, hint) VALUES (2, 'In Java switch expressions that use code blocks (`case 1: -> { ... }`), what keyword yields the result value?', 'return', 'yield', 'output', 'break', 'B', 'FINAL_ASSESSMENT', 'The yield statement was introduced to return values from multi-statement block arms of modern Java switch expressions.', NULL);
INSERT INTO questions (topic_id, question_text, option_a, option_b, option_c, option_d, correct_option, question_type, explanation, hint) VALUES (3, 'What occurs if you invoke `Arrays.sort()` on an array of custom `Student` objects that do not implement `Comparable`?', 'Sorts by memory address', 'Throws a runtime `ClassCastException`', 'Sorts alphabetically by class name', 'Silently leaves the array unchanged', 'B', 'FINAL_ASSESSMENT', 'Without a provided Comparator, Arrays.sort() casts array elements to Comparable. If not implemented, a ClassCastException is thrown.', NULL);
INSERT INTO questions (topic_id, question_text, option_a, option_b, option_c, option_d, correct_option, question_type, explanation, hint) VALUES (3, 'How does Java allocate memory for `int[][] matrix = new int[3][];`?', 'Allocates a 3x3 square matrix initialized to 0', 'Allocates an array of 3 null references on the heap, allowing each row to be allocated independently later', 'Compilation error: column dimension cannot be omitted', 'Allocates 12 bytes of continuous stack memory', 'B', 'FINAL_ASSESSMENT', 'Omitting trailing dimensions allocates the top-level array containing null references, enabling dynamic construction of ragged arrays.', NULL);
INSERT INTO questions (topic_id, question_text, option_a, option_b, option_c, option_d, correct_option, question_type, explanation, hint) VALUES (3, 'What is the difference between shallow copy and deep copy for an array of objects `Student[] arr`?', 'Shallow copy copies references; deep copy instantiates new Student objects with duplicate field values', 'Shallow copy is for numbers; deep copy is for text', 'Deep copy is automated by the = operator', 'There is no difference in Java', 'A', 'FINAL_ASSESSMENT', 'Shallow copies replicate only reference pointers. Deep copies recursively construct new instances with copied values.', NULL);
INSERT INTO questions (topic_id, question_text, option_a, option_b, option_c, option_d, correct_option, question_type, explanation, hint) VALUES (4, 'Why is defensive copying critical when designing an immutable class with a mutable field such as `Date` or `int[]`?', 'To improve garbage collection throughput', 'To prevent callers from modifying the class''s private internal state via retained outside references', 'To support serialization', 'It is required by the JVM bytecode verifier', 'B', 'FINAL_ASSESSMENT', 'Without cloning mutable objects in constructor and getter, external callers retain references to internal objects and can mutate them.', NULL);
INSERT INTO questions (topic_id, question_text, option_a, option_b, option_c, option_d, correct_option, question_type, explanation, hint) VALUES (4, 'How does constructor chaining with `this(...)` prevent code duplication in complex entity classes?', 'By allowing constructors to inherit from other classes', 'By delegating overloaded constructors to a single master constructor containing core validation logic', 'By executing constructors in background threads', 'By bypassing field initialization', 'B', 'FINAL_ASSESSMENT', 'this(...) delegates constructor calls to a canonical constructor, ensuring validation rules and defaults are maintained in one single location.', NULL);
INSERT INTO questions (topic_id, question_text, option_a, option_b, option_c, option_d, correct_option, question_type, explanation, hint) VALUES (4, 'What happens when two distinct objects have identical field values but their class has NOT overridden `equals()` and `hashCode()`?', '`obj1.equals(obj2)` returns true', '`obj1 == obj2` and `obj1.equals(obj2)` both evaluate to false', 'The compiler flags a warning', 'They cannot be added to an ArrayList', 'B', 'FINAL_ASSESSMENT', 'Default Object.equals() tests reference identity (==). Since both objects have different heap addresses, equals returns false.', NULL);
INSERT INTO questions (topic_id, question_text, option_a, option_b, option_c, option_d, correct_option, question_type, explanation, hint) VALUES (5, 'Given `SuperClass ref = new SubClass(); ref.staticMethod();`, where both classes declare `static void staticMethod()`, which method runs?', 'SubClass version, because the runtime object is SubClass', 'SuperClass version, because static methods are resolved at compile-time by the reference type', 'Throws NoSuchMethodError', 'Both methods run sequentially', 'B', 'FINAL_ASSESSMENT', 'Static methods cannot be overridden (only hidden). Method resolution is bound at compile time according to the reference variable type.', NULL);
INSERT INTO questions (topic_id, question_text, option_a, option_b, option_c, option_d, correct_option, question_type, explanation, hint) VALUES (5, 'When overriding a method in a subclass, what rule governs the access modifier of the overriding method?', 'The overriding method must be declared private', 'The overriding method cannot reduce the visibility of the superclass method; it can only maintain or expand it', 'The overriding method must use the exact same modifier', 'Access modifiers are ignored during overriding', 'B', 'FINAL_ASSESSMENT', 'A subclass method cannot reduce visibility (e.g. overriding protected with private is forbidden; expanding to public is permitted).', NULL);
INSERT INTO questions (topic_id, question_text, option_a, option_b, option_c, option_d, correct_option, question_type, explanation, hint) VALUES (5, 'What occurs if a class implements two interfaces that declare identical default methods `default void ping() { ... }`?', 'The first interface takes priority', 'Compilation fails unless the implementing class explicitly overrides the default method to resolve ambiguity', 'Both methods are executed consecutively', 'The method is deleted at runtime', 'B', 'FINAL_ASSESSMENT', 'The compiler cannot resolve diamond default method collisions automatically and requires the implementing class to override the method explicitly.', NULL);
INSERT INTO questions (topic_id, question_text, option_a, option_b, option_c, option_d, correct_option, question_type, explanation, hint) VALUES (6, 'What critical contract must be upheld between `equals()` and `hashCode()` for objects used as keys in a `HashMap`?', 'If two objects have the same hashCode(), they must be equal', 'If two objects are equal according to equals(), they must produce the exact same hashCode()', 'hashCode() must always return a positive number', 'equals() must never return true for different instances', 'B', 'FINAL_ASSESSMENT', 'The hashCode contract dictates that if a.equals(b) is true, a.hashCode() == b.hashCode() must strictly be true to guarantee bucket retrieval.', NULL);
INSERT INTO questions (topic_id, question_text, option_a, option_b, option_c, option_d, correct_option, question_type, explanation, hint) VALUES (6, 'In a `try-with-resources` block, if an exception occurs in the `try` block AND an exception is thrown while closing the resource, what happens?', 'The closing exception completely overwrites the try block exception', 'The try block exception is thrown, and the closing exception is suppressed and attached via `getSuppressed()`', 'Both exceptions cancel out', 'The application halts without throwing', 'B', 'FINAL_ASSESSMENT', 'try-with-resources preserves the primary exception from the try block and suppresses any secondary exception from close(), accessible via Throwable.getSuppressed().', NULL);
INSERT INTO questions (topic_id, question_text, option_a, option_b, option_c, option_d, correct_option, question_type, explanation, hint) VALUES (6, 'How do custom checked exceptions differ in architectural purpose from custom unchecked exceptions?', 'Checked exceptions are for performance logging; unchecked are for database operations', 'Checked exceptions represent recoverable application conditions callers should handle; unchecked represent unrecoverable errors or contract violations', 'There is no difference in modern Java architecture', 'Checked exceptions cannot contain error messages', 'B', 'FINAL_ASSESSMENT', 'Checked exceptions enforce explicit handling for recoverable business conditions, whereas unchecked (RuntimeException) exceptions signal programming bugs.', NULL);

-- 5. Ensure Final Assessment Quiz record exists in quizzes table
INSERT INTO quizzes (course_id, topic_id, quiz_type, time_limit_minutes, title)
SELECT 1, NULL, 'FINAL_ASSESSMENT', 25, 'Java Programming - Final Comprehensive Assessment'
WHERE NOT EXISTS (SELECT 1 FROM quizzes WHERE course_id = 1 AND quiz_type = 'FINAL_ASSESSMENT');
INSERT INTO quizzes (course_id, topic_id, quiz_type, time_limit_minutes, title)
SELECT 1, 5, 'CHAPTER_QUIZ', 10, 'Inheritance & Polymorphism - Topic Assessment Quiz'
WHERE NOT EXISTS (SELECT 1 FROM quizzes WHERE topic_id = 5 AND quiz_type = 'CHAPTER_QUIZ');
